package local.thor.bilichannels;
import android.graphics.*;
/** Neutral surfaces, readable type and pink accents; retains independent branding. */
final class ChannelStyle {
 static final int INK=UiStyle.INK,TEAL=UiStyle.ACCENT,PINK=UiStyle.ACCENT,LILAC=UiStyle.MUTED;
 /** Baseline for the current font, centered between the actual box edges. */
 static float centeredBaseline(Paint p,float top,float bottom){return (top+bottom-p.ascent()-p.descent())/2;}
 static void star(Canvas c,Paint p,float x,float y,float r,int color){p.setColor(color);Path s=new Path();s.moveTo(x,y-r);s.lineTo(x+r*.28f,y-r*.28f);s.lineTo(x+r,y);s.lineTo(x+r*.28f,y+r*.28f);s.lineTo(x,y+r);s.lineTo(x-r*.28f,y+r*.28f);s.lineTo(x-r,y);s.lineTo(x-r*.28f,y-r*.28f);s.close();c.drawPath(s,p);}
 static void mascot(Canvas c,Paint p,float x,float y,float size){c.save();c.translate(x,y);c.scale(size/40,size/40);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.5f);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(LILAC);c.drawLine(-8,-14,-13,-24,p);c.drawLine(8,-14,13,-24,p);p.setStyle(Paint.Style.FILL);p.setColor(0xffeee6fa);c.drawRoundRect(-23,-15,23,18,10,10,p);p.setColor(0xffffffff);c.drawRoundRect(-18,-10,18,12,7,7,p);p.setColor(INK);c.drawOval(-9,-3,-6,4,p);c.drawOval(6,-3,9,4,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.8f);c.drawArc(-4,1,4,7,10,160,false,p);p.setStyle(Paint.Style.FILL);p.setColor(0x99efa4be);c.drawOval(-14,3,-8,6,p);c.drawOval(8,3,14,6,p);star(c,p,25,-19,5,PINK);c.restore();}
 static void backdrop(Canvas c,float width,float height,boolean header){Paint p=new Paint();p.setColor(UiStyle.CANVAS);c.drawRect(0,0,width,height,p);}
 static void keyBadge(Canvas c,Paint p,String key,float x,float y,float size){p.setStyle(Paint.Style.FILL);p.setColor(0xfff1f2f3);c.drawRoundRect(x-size*.82f,y-size*.58f,x+size*.82f,y+size*.58f,size*.22f,size*.22f,p);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(size*.7f);p.setColor(0xff9499a0);c.drawText(key,x,y-(p.ascent()+p.descent())/2,p);p.setTypeface(Typeface.DEFAULT);p.setTextAlign(Paint.Align.LEFT);}
 static void dock(Canvas c,float h,String middle,String status,String clock,String hint){Paint p=new Paint(3);p.setColor(0x226b799a);c.drawRoundRect(11,h-131,469,h-3,19,19,p);p.setColor(0xfffcfcff);c.drawRoundRect(10,h-134,470,h-6,19,19,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(0xffe5e2ef);c.drawRoundRect(10,h-134,470,h-6,19,19,p);p.setStyle(Paint.Style.FILL);mascot(c,p,39,h-111,25);p.setTypeface(Typeface.DEFAULT_BOLD);p.setColor(INK);p.setTextSize(13);c.drawText("次元放映室",62,h-109,p);p.setTypeface(Typeface.DEFAULT);p.setColor(0xffeaf3f5);c.drawRoundRect(145,h-123,319,h-101,11,11,p);p.setColor(TEAL);p.setTextSize(11);c.drawText(MainActivity.ellipsize(status,p,11,157),155,h-108,p);p.setColor(0xff9297ae);p.setTextAlign(Paint.Align.RIGHT);c.drawText(clock,451,h-109,p);p.setTextAlign(Paint.Align.LEFT);
  String[] labels={"返回",middle,"更多"},keys={"B","A","Y"};for(int i=0;i<3;i++){float x=18+i*150;p.setColor(i==1?0x33fb7299:0x1461666d);c.drawRoundRect(x,h-80,x+144,h-38,UiStyle.RADIUS_CONTROL,UiStyle.RADIUS_CONTROL,p);p.setShader(new LinearGradient(x,h-83,x+144,h-41,i==1?0xffffffff:0xffffffff,i==1?0xfffff2f6:0xfff7f8fa,Shader.TileMode.CLAMP));c.drawRoundRect(x,h-84,x+144,h-42,UiStyle.RADIUS_CONTROL,UiStyle.RADIUS_CONTROL,p);p.setShader(null);p.setColor(i==1?TEAL:LILAC);c.drawCircle(x+25,h-63,10,p);p.setColor(Color.WHITE);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(11);p.setTextAlign(Paint.Align.CENTER);c.drawText(keys[i],x+25,h-59,p);p.setColor(i==1?0xffc85578:INK);p.setTextSize(labels[i].length()>3?15:17);c.drawText(labels[i],x+86,h-57,p);p.setTextAlign(Paint.Align.LEFT);}
  p.setTypeface(Typeface.DEFAULT);p.setColor(0xff9099ab);p.setTextSize(10.5f);star(c,p,27,h-22,4,PINK);c.drawText(MainActivity.ellipsize(hint,p,10.5f,412),39,h-18,p);
 }
}
